cd <E>/trials/w007/ws && node --eval "
import { shipOrder } from './src/shipping/domain/shipment.ts';
import { OrderStateError } from './src/orders/domain/order.ts';

// Test 1: Pending order should ship successfully
const pendingOrder = { id: 'o1', customerId: 'alice', status: 'pending', items: ['sku-1'] };
const shipped = shipOrder(pendingOrder);
console.log('✓ Pending order shipped:', shipped.status === 'shipped' ? 'SUCCESS' : 'FAILED');

// Test 2: Cancelled order should throw error
const cancelledOrder = { id: 'o2', customerId: 'bob', status: 'cancelled', items: ['sku-2'] };
try {
  shipOrder(cancelledOrder);
  console.log('✗ Cancelled order: FAILED (no error thrown)');
} catch (e) {
  if (e instanceof OrderStateError && e.message.includes('cancelled')) {
    console.log('✓ Cancelled order rejected with error: SUCCESS');
  } else {
    console.log('✗ Cancelled order rejected with wrong error: FAILED');
  }
}

// Test 3: Shipped order stays shipped (edge case)
const alreadyShipped = { id: 'o3', customerId: 'charlie', status: 'shipped', items: ['sku-3'] };
try {
  const result = shipOrder(alreadyShipped);
  console.log('✓ Already shipped order result:', result.status === 'shipped' ? 'SUCCESS' : 'FAILED');
} catch (e) {
  console.log('✗ Already shipped order: FAILED (unexpected error)');
}
"

